#!/usr/bin/env node
import assert from "node:assert/strict"; import fs from "node:fs"; import path from "node:path";
const args=process.argv.slice(2); const arg=(n,f="")=>{const i=args.indexOf(n);return i>=0?(args[i+1]??""):f};
const prod=new URL(arg("--base-url","https://learningbiologyforlife.org")); const exact=new URL(arg("--exact-deployment-url")); const output=arg("--output","ecology-live-evidence/ecology-v2-10-live.json"); const token=process.env.PRODUCTION_CERTIFICATION_BYPASS_TOKEN??""; assert.match(token,/^[0-9a-f]{64}$/);
const routes=["/biology/higher-zoology-tree/ecology/ecology-01-foundations-history-scope-levels/", "/en/biology/higher-zoology-tree/ecology/ecology-01-foundations-history-scope-levels/", "/biology/higher-zoology-tree/ecology/ecology-02-limiting-factors-liebig-shelford/", "/en/biology/higher-zoology-tree/ecology/ecology-02-limiting-factors-liebig-shelford/", "/biology/higher-zoology-tree/ecology/ecology-03-abiotic-light-temperature/", "/en/biology/higher-zoology-tree/ecology/ecology-03-abiotic-light-temperature/", "/biology/higher-zoology-tree/ecology/ecology-04-abiotic-water-soil-salinity/", "/en/biology/higher-zoology-tree/ecology/ecology-04-abiotic-water-soil-salinity/", "/biology/higher-zoology-tree/ecology/ecology-05-biotic-limiting-factors-interactions/", "/en/biology/higher-zoology-tree/ecology/ecology-05-biotic-limiting-factors-interactions/", "/biology/higher-zoology-tree/ecology/ecology-06-multiple-factors-adaptation/", "/en/biology/higher-zoology-tree/ecology/ecology-06-multiple-factors-adaptation/", "/biology/higher-zoology-tree/ecology/ecology-07-case-study-sundarbans-salinity/", "/en/biology/higher-zoology-tree/ecology/ecology-07-case-study-sundarbans-salinity/", "/biology/higher-zoology-tree/ecology/ecology-08-population-characteristics-density-dispersion/", "/en/biology/higher-zoology-tree/ecology/ecology-08-population-characteristics-density-dispersion/", "/biology/higher-zoology-tree/ecology/ecology-09-demography-vital-rates-life-tables/", "/en/biology/higher-zoology-tree/ecology/ecology-09-demography-vital-rates-life-tables/", "/biology/higher-zoology-tree/ecology/ecology-10-survivorship-growth-models/", "/en/biology/higher-zoology-tree/ecology/ecology-10-survivorship-growth-models/"]; assert.equal(routes.length,20); const headers={Accept:"text/html,application/xhtml+xml","x-lbfl-certification":token};
async function get(base,route){let last;for(let a=1;a<=5;a++){try{const res=await fetch(new URL(route,base),{headers,redirect:"manual",signal:AbortSignal.timeout(20000)});const text=await res.text();if(res.status===200)return{res,text};last=new Error(`${route} -> ${res.status}`)}catch(e){last=e}await new Promise(r=>setTimeout(r,a*1000))}throw last}
function canonical(html){for(const tag of html.match(/<link\b[^>]*>/gi)??[]){if(/rel=["'][^"']*canonical/i.test(tag)){const m=tag.match(/href=["']([^"']+)/i);if(m)return m[1]}}return""}
const results=[];for(const route of routes){const p=await get(prod,route),e=await get(exact,route);assert.match(p.res.headers.get("content-type")??"",/^text\/html/i);assert.equal(new URL(canonical(p.text)).pathname,route);assert.equal(new URL(canonical(e.text)).pathname,route);results.push({route,production:p.res.status,exact:e.res.status})}
for(const route of ["/biology/higher-zoology-tree/ecology/","/en/biology/higher-zoology-tree/ecology/","/biology/higher-zoology-tree/ecology/course-index/","/ecology-sitemap.xml","/robots.txt"]){await get(prod,route)}
const report={token:"ECOLOGY_V2_10_LIVE_PASS",lecture_pages:"20/20",exact_deployment:"20/20",canonical_match:"20/20"};fs.mkdirSync(path.dirname(output),{recursive:true});fs.writeFileSync(output,JSON.stringify(report,null,2)+"\n");console.log("ECOLOGY_V2_10_LIVE_PASS");console.log("lecture_pages=20/20");console.log("exact_deployment=20/20");console.log("canonical_match=20/20");
